function () {
                    // 验证成功后的回调                   
                    var tip = "";
                    var result = window.fCheck.config.result; //滑动验证码验证参数
                    //校验
                    if (that.username.val() == '') {
                        validate.displayPswdLoginResult('请输入用户名/邮箱/手机号', '', that);
                        that.reInitSlideMathCode();
                        return;
                    }
                    if (that.password.val() == '') {
                        validate.displayPswdLoginResult('请输入密码', '', that);
                        that.reInitSlideMathCode();
                        return;
                    }
                    else {
                        var res = validate.isPassword(that.password.val());
                        if (res == true) {
                            that.passwordFlag = true;
                        }
                        else {
                            validate.displayPswdLoginResult(res, '', that);
                            that.passwordFlag = false;
                            that.reInitSlideMathCode();
                            return;
                        }
                    }
                    jQuery.ajax({
                        url: '/loginwithpwdStrong.api',
                        type: 'Post',
                        dataType: 'json',
                        async: false,
                        xhrFields: {
                            withCredentials: true
                        },
                        data: {
                            uid: that.username.val(),
                            pwd: encryptedString(key_to_encode, that.password.val()),
                            Service: that.service.val(),
                            AutoLogin: that.autoLogin.val(),
                            Operatetype: "0",
                            Gt: result.fc_gt,
                            Challenge: result.fc_challenge,
                            Validate: result.fc_validate
                        },
                        error: function (data) {
                            that.enableLoginBtn(that);
                            validate.displayPswdLoginResult('服务器开小差了，请重试', '', that);
                            that.reInitSlideMathCode();
                        },
                        success: function (json) {
                            if (json.Message == "Success") {
                                if (validate.isPasswordForV(that.password.val(), 1) != true) {
                                    alert("您的账号密码过于简单，建议修改为安全性更高的密码。您可稍后在“我的房天下”中修改。");
                                }
                                var burl = that.burl.val()
                                if (burl && json.PToken) {
                                    burl = that.middleUrl.val() + "?backurl=" + burl + '&ptoken=' + json.PToken;
                                }
                                validate.displayPswdLoginResult("登录成功", burl, that);
                            } else if (json.Message === "Success" && json.needresetpwd === "1") {
                                debugger;
                                if (confirm(json.alertsetpwdmsg)) {
                                    var truebackurl = location.origin;
                                    var tipstring = encodeURI(json.alertsetpwdmsg.toString()).toString();
                                    window.location.href = 'http://my.fang.com/Account/UpdatePassword.html' + '?needresetpwd=' + json.needresetpwd + '&tip=' + tipstring + '&backurl=' + truebackurl;
                                    return;
                                }
                                ShowWrong('登录成功');
                                var backurl = $('#backurl').val();
                                if (backurl === "") {
                                    backurl = "http://my.fang.com"
                                }
                                if (channelcode) {
                                    window.location.href = backurl + "?channelcode=" + channelcode;
                                } else {
                                    window.location.href = backurl;
                                }
                            } else if (json.Message === "Error" && json.needresetpwd === "2") {
                                debugger;
                                var errorbackurl = location.origin;
                                alert(json.alertsetpwdmsg);
                                var tipstring = encodeURI(json.alertsetpwdmsg.toString()).toString();
                                window.location.href = 'http://my.fang.com/Account/UpdatePassword.html' + '?needresetpwd=' + json.needresetpwd + '&tip=' + tipstring + '&backurl=' + errorbackurl;
                            } else {
                                if (json.LoginErrorCount > 5 || json.IsIpCanVisit == "false" || json.IsIpCanVisit == false) {
                                    that.disenableLoginBtn(that);
                                    if (json.LoginErrorCount > 5 && json.LoginErrorCount != 999) {
                                        validate.displayPswdLoginResult(json.Tip, '', that);
                                        alert(json.Tip);
                                    }
                                    else {
                                        that.initSlideMathCode(that);
                                        validate.displayPswdLoginMathCode(that);
                                    }
                                } else {
                                    if (json.LoginErrorCount >=2) {
                                    that.initSlideMathCode(that);
                                    validate.displayPswdLoginMathCode(that);
                                     }
                                    validate.displayPswdLoginResult(json.Tip, '', that);
									window.fCheck.reinit();
                                }
                            }

                        }
                    });

                }

function (pwd) {//判断密码是否合法
            var passwordReg = /^[\u0000-\u00FF]{6,16}$/;
            if (!passwordReg.test(pwd)) {
                return "密码错误";
                //return "密码为6到16位的半角字符(英文字母，字符，数字及其组合)";
            }
            return true;
        }

